    #[test]
    fn jbc_base64_binary_and_stdin_rows_match_upstream() {
        // Mirrors packages/just-bash/src/commands/base64/base64.binary.test.ts and
        // base64.test.ts:156. Each assertion fails if the byte-exact base64
        // encode/decode round-trip through virtual files or ASCII/UTF-8 stdin
        // regresses. Raw non-UTF-8 binary piped through stdin (binary.test.ts:65
        // round-trip, :172 large pipe) stays portable-pending because the virtual
        // pipeline carries stdin/stdout as UTF-8 byte-strings and cannot represent
        // arbitrary non-UTF-8 bytes mid-pipe without a crate-wide Vec<u8> pipe.
        let bash = JustBashSession::with_options(JustBashSessionOptions::new());
        let write = |path: &str, bytes: Vec<u8>| {
            bash.inner
                .fs
                .lock()
                .unwrap()
                .write_file(path, bytes)
                .unwrap();
        };

        // base64.binary.test.ts:6 should encode binary file with high bytes.
        write("/binary.bin", vec![0x80, 0x90, 0xa0, 0xb0, 0xff]);
        let high = bash.exec("base64 /binary.bin", JustBashExecOptions::new());
        assert_eq!(high.exit_code, 0);
        assert_eq!(high.stdout.trim(), "gJCgsP8=");
        assert!(
            high.stdout
                .trim()
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'+' || b == b'/' || b == b'=')
        );

        // base64.binary.test.ts:19 should encode and decode file with null bytes.
        write("/nulls.bin", vec![0x41, 0x00, 0x42, 0x00, 0x43]);
        bash.exec(
            "base64 /nulls.bin > /encoded.txt",
            JustBashExecOptions::new(),
        );
        let nulls = bash.exec("base64 -d /encoded.txt", JustBashExecOptions::new());
        assert_eq!(nulls.stdout.as_bytes(), &[0x41, 0x00, 0x42, 0x00, 0x43]);

        // base64.binary.test.ts:32 should encode and decode file with all byte values.
        write("/allbytes.bin", (0u8..=255).collect::<Vec<_>>());
        bash.exec(
            "base64 /allbytes.bin > /allenc.txt",
            JustBashExecOptions::new(),
        );
        bash.exec(
            "base64 -d /allenc.txt > /allout.bin",
            JustBashExecOptions::new(),
        );
        let allbytes = bash
            .inner
            .fs
            .lock()
            .unwrap()
            .read_file_buffer("/allout.bin")
            .unwrap();
        assert_eq!(allbytes.len(), 256);
        assert_eq!(allbytes, (0u8..=255).collect::<Vec<_>>());

        // base64.binary.test.ts:52 should encode binary data from stdin
        // (upstream asserts only exit 0 and non-empty output).
        write("/stdinbin.bin", vec![0x80, 0xff, 0x90, 0xab]);
        let stdin_enc = bash.exec("cat /stdinbin.bin | base64", JustBashExecOptions::new());
        assert_eq!(stdin_enc.exit_code, 0);
        assert!(!stdin_enc.stdout.trim().is_empty());

        // base64.binary.test.ts:82 should decode base64 from stdin ("Hello").
        write("/hello-b64.txt", b"SGVsbG8=\n".to_vec());
        let dec_hello = bash.exec("cat /hello-b64.txt | base64 -d", JustBashExecOptions::new());
        assert_eq!(dec_hello.stdout, "Hello");

        // base64.binary.test.ts:94 should decode valid base64 from stdin ("ABC").
        write("/abc-b64.txt", b"QUJD\n".to_vec());
        let dec_abc = bash.exec("cat /abc-b64.txt | base64 -d", JustBashExecOptions::new());
        assert_eq!(dec_abc.stdout, "ABC");

        // base64.binary.test.ts:108 should round-trip text content via files.
        write("/data.txt", b"Hello World 123".to_vec());
        bash.exec(
            "base64 /data.txt > /data-enc.txt",
            JustBashExecOptions::new(),
        );
        let rt_text = bash.exec("base64 -d /data-enc.txt", JustBashExecOptions::new());
        assert_eq!(rt_text.stdout, "Hello World 123");

        // base64.binary.test.ts:121 should round-trip ASCII text via stdin.
        write("/data2.txt", b"test content".to_vec());
        bash.exec(
            "cat /data2.txt | base64 > /data2-enc.txt",
            JustBashExecOptions::new(),
        );
        let rt_stdin = bash.exec("base64 -d /data2-enc.txt", JustBashExecOptions::new());
        assert_eq!(rt_stdin.stdout, "test content");

        // base64.binary.test.ts:134 should handle large binary files (1MB+) via files.
        let size = 1024 * 1024usize;
        let large: Vec<u8> = (0..size).map(|i| (i % 256) as u8).collect();
        write("/large.bin", large.clone());
        bash.exec(
            "base64 /large.bin > /large-enc.txt",
            JustBashExecOptions::new(),
        );
        bash.exec(
            "base64 -d /large-enc.txt > /large-dec.bin",
            JustBashExecOptions::new(),
        );
        let decoded = bash
            .inner
            .fs
            .lock()
            .unwrap()
            .read_file_buffer("/large-dec.bin")
            .unwrap();
        assert_eq!(decoded.len(), size);
        assert_eq!(decoded[0], 0);
        assert_eq!(decoded[255], 255);
        assert_eq!(decoded[size / 2], ((size / 2) % 256) as u8);
        assert_eq!(decoded[size - 1], ((size - 1) % 256) as u8);
        for i in (0..size).step_by(10000) {
            assert_eq!(decoded[i], (i % 256) as u8);
        }

        // base64.test.ts:156 should encode binary data with invalid UTF-8 bytes
        // (PNG magic bytes, 0x89 is invalid UTF-8).
        write("/png.dat", vec![0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a]);
        let png = bash.exec("base64 /png.dat", JustBashExecOptions::new());
        assert_eq!(png.stdout, "iVBORw0K\n");
        assert_eq!(png.exit_code, 0);

        // base64.test.ts:170 should encode binary file with null bytes.
        write("/nulls.dat", vec![0x00, 0x00, 0x00, 0x00]);
        let nulls_dat = bash.exec("base64 /nulls.dat", JustBashExecOptions::new());
        assert_eq!(nulls_dat.stdout, "AAAAAA==\n");
        assert_eq!(nulls_dat.exit_code, 0);

        // base64.test.ts:182 should encode binary file with high bytes.
        write("/high.dat", vec![0xff, 0xfe, 0xfd, 0xfc]);
        let high_dat = bash.exec("base64 /high.dat", JustBashExecOptions::new());
        assert_eq!(high_dat.stdout, "//79/A==\n");
        assert_eq!(high_dat.exit_code, 0);

        // base64.binary.test.ts:172 should handle large files via pipe. A 512KB
        // binary file (pattern (i*7)%256, full 0..255 byte range) is round-tripped
        // through a multi-stage pipe `cat | base64 | base64 -d > file`. The first
        // stage reads raw bytes from the virtual file and marks the pipe stdin as
        // a byte buffer; `base64` (encode) now recovers those exact bytes from the
        // latin1 carrier instead of UTF-8 re-encoding them, so the encode/decode
        // round-trip writes the original bytes back verbatim.
        let pipe_size = 512 * 1024usize;
        let pattern: Vec<u8> = (0..pipe_size).map(|i| ((i * 7) % 256) as u8).collect();
        write("/medium.bin", pattern.clone());
        let pipe = bash.exec(
            "cat /medium.bin | base64 | base64 -d > /output.bin",
            JustBashExecOptions::new(),
        );
        assert_eq!(pipe.exit_code, 0);
        let output = bash
            .inner
            .fs
            .lock()
            .unwrap()
            .read_file_buffer("/output.bin")
            .unwrap();
        assert_eq!(output.len(), pipe_size);
        for i in (0..pipe_size).step_by(5000) {
            assert_eq!(output[i], ((i * 7) % 256) as u8);
        }
        // Full byte-exact equality so any mid-pipe corruption fails the test.
        assert_eq!(output, pattern);
    }

    // Helper mirroring upstream `parseWidthPrecision`'s observable result
    // ([width, precision, _consumed]) on top of the Rust `parse_printf_directive`.
    // The Rust parser stores left-justify as a flag plus an unsigned width; here
    // we reconstruct the signed width (negative => left-justify) and map the
    // `Option<usize>` width/precision to upstream's `0`/`-1` sentinels so the
    // numeric expectations line up 1:1.
    fn parse_width_precision(spec: &str) -> (i64, i64) {
        let mut chars = spec.chars().peekable();
        let directive = parse_printf_directive(&mut chars);
        let mut width = directive.width.unwrap_or(0) as i64;
        if directive.left_justify && width > 0 {
            width = -width;
        }
        let precision = directive.precision.map_or(-1, |value| value as i64);
        (width, precision)
    }

    #[test]
    fn printf_width_precision_parse_and_apply_match_upstream_escapes_helpers() {
        // Mirrors packages/just-bash/src/commands/printf/escapes.test.ts:152
        // (applyWidth) and :158/:165/:172/:179/:186 (parseWidthPrecision). Each
        // assertion fails if the width/precision parsing or padding regresses.

        // escapes.test.ts:152 applyWidth("hello", 3, -1) -> "hello"
        // (no padding when the value is longer than the field width).
        let directive = PrintfDirective {
            left_justify: false,
            zero_pad: false,
            width: Some(3),
            precision: None,
            specifier: 's',
        };
        assert_eq!(
            apply_printf_width("hello".to_string(), &directive, false),
            "hello"
        );

        // escapes.test.ts:158 parseWidthPrecision("10f", 0) -> [10, -1, 2]
        assert_eq!(parse_width_precision("10f"), (10, -1));

        // escapes.test.ts:165 parseWidthPrecision("-20s", 0) -> [-20, -1, 3]
        assert_eq!(parse_width_precision("-20s"), (-20, -1));

        // escapes.test.ts:172 parseWidthPrecision(".5f", 0) -> [0, 5, 2]
        assert_eq!(parse_width_precision(".5f"), (0, 5));

        // escapes.test.ts:179 parseWidthPrecision("-10.5s", 0) -> [-10, 5, 5]
        assert_eq!(parse_width_precision("-10.5s"), (-10, 5));

        // escapes.test.ts:186 parseWidthPrecision("f", 0) -> [0, -1, 0]
        assert_eq!(parse_width_precision("f"), (0, -1));
    }

    #[test]
    fn jbc46_checksum_commands_hash_check_and_binary_rows_are_virtual() {
        let bash = JustBashSession::with_options(
            JustBashSessionOptions::new()
                .with_file("/hello.txt", "hello")
                .with_file("/empty.txt", "")
                .with_file("/unicode.txt", "Hello 中文 日本語")
                .with_file("/binary.bin", "A\0B\0C"),
        );
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/png.bin", vec![0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a])
            .unwrap();
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/png4.bin", vec![0x89, 0x50, 0x4e, 0x47])
            .unwrap();
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/allbytes.bin", (0u8..=255).collect::<Vec<_>>())
            .unwrap();

        assert_eq!(
            bash.exec("echo -n hello | md5sum", JustBashExecOptions::new())
                .stdout,
            "5d41402abc4b2a76b9719d911017c592  -\n"
        );
        assert_eq!(
            bash.exec("md5sum /empty.txt", JustBashExecOptions::new())
                .stdout,
            "d41d8cd98f00b204e9800998ecf8427e  /empty.txt\n"
        );
        assert_eq!(
            bash.exec("sha1sum /hello.txt", JustBashExecOptions::new())
                .stdout,
            "aaf4c61ddcc5e8a2dabede0f3b482cd9aea9434d  /hello.txt\n"
        );
        assert_eq!(
            bash.exec("echo -n '' | sha1sum", JustBashExecOptions::new())
                .stdout,
            "da39a3ee5e6b4b0d3255bfef95601890afd80709  -\n"
        );
        assert_eq!(
            bash.exec("sha256sum /hello.txt", JustBashExecOptions::new())
                .stdout,
            "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824  /hello.txt\n"
        );
        assert_eq!(
            bash.exec("echo -n '' | sha256sum", JustBashExecOptions::new())
                .stdout,
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855  -\n"
        );
        assert!(
            bash.exec("sha256sum --help", JustBashExecOptions::new())
                .stdout
                .contains("SHA256")
        );

        bash.exec(
            "md5sum /hello.txt /binary.bin > /checksums.txt",
            JustBashExecOptions::new(),
        );

        assert!(
            bash.exec("tar --help", JustBashExecOptions::new())
                .stdout
                .contains("tar - manipulate tape archives")
        );
        assert_eq!(
            bash.exec("tar -f /archive.tar", JustBashExecOptions::new())
                .exit_code,
            2
        );
        assert_eq!(
            bash.exec("tar -c -x -f /archive.tar", JustBashExecOptions::new())
                .exit_code,
            2
        );
        assert_eq!(
            bash.exec(
                "tar -c --unknown-option /project",
                JustBashExecOptions::new()
            )
            .exit_code,
            1
        );
        assert_eq!(
            bash.exec("tar -c -f", JustBashExecOptions::new()).exit_code,
            2
        );
        let check = bash.exec("md5sum -c /checksums.txt", JustBashExecOptions::new());
        assert_eq!(check.exit_code, 0);
        assert!(check.stdout.contains("/hello.txt: OK"));
        assert!(check.stdout.contains("/binary.bin: OK"));

        bash.exec("echo changed > /hello.txt", JustBashExecOptions::new());
        let failed = bash.exec("md5sum -c /checksums.txt", JustBashExecOptions::new());
        assert_eq!(failed.exit_code, 1);
        assert!(failed.stdout.contains("/hello.txt: FAILED"));
        assert!(failed.stdout.contains("WARNING"));

        let unicode = bash.exec("md5sum /unicode.txt", JustBashExecOptions::new());
        assert_eq!(unicode.exit_code, 0);
        assert!(unicode.stdout.contains("/unicode.txt"));
        assert_eq!(
            bash.exec("md5sum /png.bin", JustBashExecOptions::new())
                .stdout,
            "8eece9cc616084e69299f7f1a53a6404  /png.bin\n"
        );
        assert_eq!(
            bash.exec("sha256sum /png4.bin", JustBashExecOptions::new())
                .stdout,
            "0f4636c78f65d3639ece5a064b5ae753e3408614a14fb18ab4d7540d2c248543  /png4.bin\n"
        );
        let sha1_binary = bash.exec("sha1sum /png.bin", JustBashExecOptions::new());
        assert_eq!(sha1_binary.exit_code, 0);
        assert_eq!(
            sha1_binary.stdout.split_whitespace().next().unwrap().len(),
            40
        );
        let sha256_allbytes = bash.exec("sha256sum /allbytes.bin", JustBashExecOptions::new());
        assert_eq!(sha256_allbytes.exit_code, 0);
        assert_eq!(
            sha256_allbytes
                .stdout
                .split_whitespace()
                .next()
                .unwrap()
                .len(),
            64
        );
    }

    #[test]
    fn jbc46_checksum_binary_and_utf8_stdin_rows_hash_raw_bytes() {
        let bash = JustBashSession::with_options(JustBashSessionOptions::new());
        // checksum.binary.test.ts:33 / :76 / :118 - stdin with binary data:
        // Uint8Array([0x80, 0xff, 0x90, 0xab]) piped via `cat /binary.bin | <cmd>`.
        // Upstream only asserts exit 0 and a digest-shaped first field, which is
        // what each branch below checks (matching /^[a-f0-9]{N}\s+/).
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/binary.bin", vec![0x80, 0xff, 0x90, 0xab])
            .unwrap();

        let md5 = bash.exec("cat /binary.bin | md5sum", JustBashExecOptions::new());
        assert_eq!(md5.exit_code, 0); // checksum.binary.test.ts:41
        let md5_hash = md5.stdout.split_whitespace().next().unwrap();
        assert_eq!(md5_hash.len(), 32); // checksum.binary.test.ts:42
        assert!(md5_hash.bytes().all(|b| b.is_ascii_hexdigit()));

        let sha256 = bash.exec("cat /binary.bin | sha256sum", JustBashExecOptions::new());
        assert_eq!(sha256.exit_code, 0); // checksum.binary.test.ts:84
        let sha256_hash = sha256.stdout.split_whitespace().next().unwrap();
        assert_eq!(sha256_hash.len(), 64); // checksum.binary.test.ts:85
        assert!(sha256_hash.bytes().all(|b| b.is_ascii_hexdigit()));

        let sha1 = bash.exec("cat /binary.bin | sha1sum", JustBashExecOptions::new());
        assert_eq!(sha1.exit_code, 0); // checksum.binary.test.ts:126
        let sha1_hash = sha1.stdout.split_whitespace().next().unwrap();
        assert_eq!(sha1_hash.len(), 40); // checksum.binary.test.ts:127
        assert!(sha1_hash.bytes().all(|b| b.is_ascii_hexdigit()));

        // checksum.binary.test.ts:45 - identical binary content hashes identically.
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/a.bin", vec![0x80, 0x90, 0xa0])
            .unwrap();
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/b.bin", vec![0x80, 0x90, 0xa0])
            .unwrap();
        let hash_a = bash
            .exec("md5sum /a.bin", JustBashExecOptions::new())
            .stdout;
        let hash_b = bash
            .exec("md5sum /b.bin", JustBashExecOptions::new())
            .stdout;
        let first =
            |s: &str| -> String { s.split_whitespace().next().unwrap_or_default().to_string() };
        assert_eq!(first(&hash_a), first(&hash_b)); // checksum.binary.test.ts:58
        // The digest of [0x80,0x90,0xa0] is well-known; pin it so a regression
        // in binary file reads is caught, not just self-consistency.
        assert_eq!(first(&hash_a), "4a3924f9668b45471825f086276745ed");

        // checksum.binary.test.ts:145 - sha256sum of UTF-8 stdin (🚀🎉🔥).
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/emoji.txt", "🚀🎉🔥")
            .unwrap();
        let sha_utf8 = bash.exec("cat /emoji.txt | sha256sum", JustBashExecOptions::new());
        assert_eq!(sha_utf8.exit_code, 0); // checksum.binary.test.ts:153
        assert_eq!(first(&sha_utf8.stdout).len(), 64); // checksum.binary.test.ts:154
        // Hashing the raw UTF-8 bytes (12 bytes) yields this exact digest.
        assert_eq!(
            first(&sha_utf8.stdout),
            "8289878d97a2366b4cef36cd8264f330dc3cb978e29636c9aba665e8a1c9fb51"
        );

        // checksum.binary.test.ts:157 - identical UTF-8 content hashes identically.
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/a.txt", "Привет мир")
            .unwrap();
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/b.txt", "Привет мир")
            .unwrap();
        let utf_a = bash
            .exec("md5sum /a.txt", JustBashExecOptions::new())
            .stdout;
        let utf_b = bash
            .exec("md5sum /b.txt", JustBashExecOptions::new())
            .stdout;
        assert_eq!(first(&utf_a), first(&utf_b)); // checksum.binary.test.ts:170

        // checksum.binary.test.ts:189 - modified binary file fails check mode.
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/mod.bin", vec![0x80, 0x90, 0xa0])
            .unwrap();
        bash.exec(
            "md5sum /mod.bin > /checksums.txt",
            JustBashExecOptions::new(),
        );
        // Mutate the file to different bytes.
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/mod.bin", vec![0x81, 0x90, 0xa0])
            .unwrap();
        let modified = bash.exec("md5sum -c /checksums.txt", JustBashExecOptions::new());
        assert_eq!(modified.exit_code, 1); // checksum.binary.test.ts:201
        assert!(modified.stdout.contains("FAILED")); // checksum.binary.test.ts:202

        // md5sum.utf8-stdin.test.ts:5 - md5sum hashes the raw UTF-8 bytes of
        // "한글" (ed 95 9c ea b8 80), not a double-encoded form.
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/in.txt", "한글")
            .unwrap();
        let utf8_stdin = bash.exec("cat /in.txt | md5sum", JustBashExecOptions::new());
        assert_eq!(utf8_stdin.exit_code, 0);
        assert_eq!(utf8_stdin.stdout, "52b8c54ab4ea672ee6cdfdfef0a31db4  -\n");
    }

    #[test]
    fn jbc46_virtual_tar_archive_round_trips_list_extract_and_codecs() {
        let bash = JustBashSession::with_options(
            JustBashSessionOptions::new()
                .with_file("/project/src/main.js", "console.log('hello');")
                .with_file("/project/src/utils.js", "export const helper = () => {};")
                .with_file("/project/README.md", "# Project\n")
                .with_file("/logs/keep.txt", "keep")
                .with_file("/logs/skip.log", "skip")
                .with_file("/deep/nested/path/file.txt", "Content"),
        );
        bash.inner
            .fs
            .lock()
            .unwrap()
            .write_file("/project/src/high.bin", vec![0x80, 0x90, 0xa0, 0xb0, 0xff])
            .unwrap();

        let create = bash.exec(
            "tar -cvf /project.tar /project --exclude='*.log'",
            JustBashExecOptions::new(),
        );
        assert_eq!(create.exit_code, 0);
        assert!(create.stderr.contains("project"));
        let list = bash.exec("tar -tf /project.tar", JustBashExecOptions::new());
        assert!(list.stdout.contains("project/src/main.js"));
        assert!(list.stdout.contains("project/README.md"));

        bash.exec("rm -rf /project", JustBashExecOptions::new());
        let extract = bash.exec("tar -xvf /project.tar", JustBashExecOptions::new());
        assert_eq!(extract.exit_code, 0);
        assert!(extract.stderr.contains("project/src/main.js"));
        assert_eq!(
            bash.exec("cat /project/src/main.js", JustBashExecOptions::new())
                .stdout,
            "console.log('hello');"
        );

        assert_eq!(
            bash.exec(
                "tar -cf /strip.tar /deep/nested/path/file.txt; mkdir /dest; tar -xf /strip.tar -C /dest --strip=3; cat /dest/file.txt",
                JustBashExecOptions::new()
            )
            .stdout,
            "Content"
        );

        let gzip_roundtrip = bash.exec(
            "tar -czf /backup.tar.gz /project; rm -rf /project; tar -xzf /backup.tar.gz; cat /project/README.md",
            JustBashExecOptions::new(),
        );
        assert_eq!(gzip_roundtrip.exit_code, 0);
        assert!(gzip_roundtrip.stdout.contains("# Project"));
        assert!(
            bash.exec("tar -tjf /backup.tar.gz", JustBashExecOptions::new())
                .stderr
                .is_empty()
        );

        let bzip_roundtrip = bash.exec(
            "tar -cjf /backup.tar.bz2 /logs; rm -rf /logs; tar -xjf /backup.tar.bz2; cat /logs/keep.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(bzip_roundtrip.exit_code, 0);
        assert_eq!(bzip_roundtrip.stdout, "keep");

        let stdout_extract = bash.exec(
            "tar -xOf /backup.tar.bz2 /logs/keep.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(stdout_extract.stdout, "keep");

        let blocked = bash.exec(
            "tar -cJf /blocked.tar.xz /logs/keep.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(blocked.exit_code, 2);
        assert!(blocked.stderr.contains("disabled by default"));

        bash.exec(
            "tar -cf /binary.tar /project/src/high.bin; rm /project/src/high.bin; tar -xf /binary.tar",
            JustBashExecOptions::new(),
        );
        assert_eq!(
            bash.read_file_buffer("/project/src/high.bin").unwrap(),
            vec![0x80, 0x90, 0xa0, 0xb0, 0xff]
        );
    }

    #[test]
    fn r10jb_tar_bundle_create_list_extract_codecs_and_option_rows() {
        // tar.bundle.test.ts: behavior of the bundled tar binary mirrored on the
        // in-process Rust session (the bundle drives the same command surface).
        let bash = JustBashSession::new();

        // should show help
        let help = bash.exec("tar --help", JustBashExecOptions::new());
        assert_eq!(help.exit_code, 0);
        assert!(help.stdout.contains("Usage:"));
        assert!(help.stdout.contains("tar"));

        // should create and list a tar archive
        let list = bash.exec(
            "mkdir -p /tartest; echo hello > /tartest/file1.txt; echo world > /tartest/file2.txt; \
             tar -cf /test.tar -C /tartest file1.txt file2.txt; tar -tf /test.tar",
            JustBashExecOptions::new(),
        );
        assert_eq!(list.exit_code, 0);
        assert!(list.stdout.contains("file1.txt"));
        assert!(list.stdout.contains("file2.txt"));

        // should create and extract a tar archive
        let extract = bash.exec(
            "mkdir -p /src; echo content123 > /src/data.txt; \
             tar -cf /archive.tar -C /src data.txt; mkdir -p /dest; \
             tar -xf /archive.tar -C /dest; cat /dest/data.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(extract.exit_code, 0);
        assert!(extract.stdout.contains("content123"));

        // should create and extract a gzip-compressed archive
        let gzip = bash.exec(
            "mkdir -p /gztest; echo 'gzip content' > /gztest/file.txt; \
             tar -czf /test.tar.gz -C /gztest file.txt; mkdir -p /gzout; \
             tar -xzf /test.tar.gz -C /gzout; cat /gzout/file.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(gzip.exit_code, 0);
        assert!(gzip.stdout.contains("gzip content"));

        // should create and extract a bzip2-compressed archive
        let bzip2 = bash.exec(
            "mkdir -p /bz2test; echo 'bzip2 content' > /bz2test/file.txt; \
             tar -cjf /test.tar.bz2 -C /bz2test file.txt; mkdir -p /bz2out; \
             tar -xjf /test.tar.bz2 -C /bz2out; cat /bz2out/file.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(bzip2.exit_code, 0);
        assert!(bzip2.stdout.contains("bzip2 content"));

        // should reject xz native codec by default
        let xz = bash.exec(
            "tar -cJf /test.tar.xz -C / file.txt 2>&1 || echo XZ_REJECTED",
            JustBashExecOptions::new(),
        );
        assert!(xz.stdout.contains("XZ_REJECTED"));

        // should reject zstd native codec by default
        let zstd = bash.exec(
            "tar --zstd -cf /test.tar.zst -C / file.txt 2>&1 || echo ZSTD_REJECTED",
            JustBashExecOptions::new(),
        );
        assert!(zstd.stdout.contains("ZSTD_REJECTED"));

        // should auto-detect compression from filename (-a)
        let auto = bash.exec(
            "mkdir -p /autotest; echo 'auto content' > /autotest/file.txt; \
             tar -caf /auto.tar.gz -C /autotest file.txt; mkdir -p /autoout; \
             tar -xf /auto.tar.gz -C /autoout; cat /autoout/file.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(auto.exit_code, 0);
        assert!(auto.stdout.contains("auto content"));

        // should use files-from (-T)
        let from = bash.exec(
            "mkdir -p /ttest; echo file1 > /ttest/a.txt; echo file2 > /ttest/b.txt; \
             echo file3 > /ttest/c.txt; printf 'a.txt\\nc.txt\\n' > /filelist.txt; \
             tar -cf /ttest.tar -C /ttest -T /filelist.txt; tar -tf /ttest.tar",
            JustBashExecOptions::new(),
        );
        assert_eq!(from.exit_code, 0);
        assert!(from.stdout.contains("a.txt"));
        assert!(from.stdout.contains("c.txt"));
        assert!(!from.stdout.contains("b.txt"));

        // should use exclude-from (-X)
        let exclude_from = bash.exec(
            "mkdir -p /xtest; echo file1 > /xtest/a.txt; echo file2 > /xtest/b.txt; \
             echo file3 > /xtest/c.txt; echo b.txt > /excludelist.txt; \
             tar -cf /xtest.tar -C /xtest -X /excludelist.txt .; tar -tf /xtest.tar",
            JustBashExecOptions::new(),
        );
        assert_eq!(exclude_from.exit_code, 0);
        assert!(exclude_from.stdout.contains("a.txt"));
        assert!(exclude_from.stdout.contains("c.txt"));
        assert!(!exclude_from.stdout.contains("b.txt"));

        // should preserve file permissions (tar -tvf surfaces the mode column)
        let perms = bash.exec(
            "mkdir -p /permtest; echo script > /permtest/run.sh; chmod 755 /permtest/run.sh; \
             tar -cf /perm.tar -C /permtest run.sh; tar -tvf /perm.tar",
            JustBashExecOptions::new(),
        );
        assert_eq!(perms.exit_code, 0);
        assert!(perms.stdout.contains("rwxr-xr-x"));

        // should handle verbose output (-v) on stderr
        let verbose = bash.exec(
            "mkdir -p /vtest; echo data > /vtest/file.txt; \
             tar -cvf /verbose.tar -C /vtest file.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(verbose.exit_code, 0);
        assert!(verbose.stderr.contains("file.txt"));
    }

    #[test]
    fn r10jb_tar_security_traversal_leading_slash_symlink_and_codec_gates() {
        // tar.security.test.ts: parent-traversal entries are blocked on extract by default.
        let bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/cage/secret.txt", "escape-attempt"),
        );
        // Archive a `../secret.txt` entry name by creating from a nested cwd.
        let create = bash.exec(
            "mkdir -p /cage/inner; tar -cf /attack.tar -C /cage/inner ../secret.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(create.exit_code, 0);
        let listed = bash.exec("tar -tf /attack.tar", JustBashExecOptions::new());
        assert!(listed.stdout.contains("../secret.txt"));
        let blocked = bash.exec(
            "mkdir /safe && tar -xf /attack.tar -C /safe",
            JustBashExecOptions::new(),
        );
        assert_eq!(blocked.exit_code, 2);
        assert!(blocked.stderr.contains("Path contains '..'"));
        assert!(!bash.file_exists("/safe/secret.txt"));

        // strips leading slash from archive entries by default
        let abs_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/abs.txt", "abs"),
        );
        let abs_create = abs_bash.exec("tar -cf /abs.tar /abs.txt", JustBashExecOptions::new());
        assert_eq!(abs_create.exit_code, 0);
        assert!(
            abs_bash
                .exec("tar -tf /abs.tar", JustBashExecOptions::new())
                .stdout
                .contains("abs.txt")
        );
        let stripped = abs_bash.exec(
            "mkdir /safe && tar -xf /abs.tar -C /safe",
            JustBashExecOptions::new(),
        );
        assert_eq!(stripped.exit_code, 0);
        assert_eq!(stripped.stderr, "");
        assert!(abs_bash.file_exists("/safe/abs.txt"));

        // allows absolute archive extraction with -P/--absolute-names
        let p_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/abs.txt", "abs"),
        );
        p_bash.exec("tar -cf /abs.tar /abs.txt", JustBashExecOptions::new());
        p_bash.exec("rm /abs.txt", JustBashExecOptions::new());
        let absolute = p_bash.exec(
            "mkdir /safe && tar -xPf /abs.tar -C /safe",
            JustBashExecOptions::new(),
        );
        assert_eq!(absolute.exit_code, 0);
        assert_eq!(absolute.stderr, "");
        assert!(p_bash.file_exists("/abs.txt"));
        assert!(!p_bash.file_exists("/safe/abs.txt"));

        // blocks unsafe symlink targets by default
        let link_bash = JustBashSession::new();
        let link_create = link_bash.exec(
            "mkdir -p /work; ln -s ../outside /work/link.txt; tar -cf /link.tar -C /work link.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(link_create.exit_code, 0);
        let link_blocked = link_bash.exec(
            "mkdir /safe && tar -xf /link.tar -C /safe",
            JustBashExecOptions::new(),
        );
        assert_eq!(link_blocked.exit_code, 2);
        assert!(link_blocked.stderr.contains("unsafe symlink target"));
        assert!(!link_bash.file_exists("/safe/link.txt"));

        // blocks xz encode by default (native codec risk)
        let xz_bash = JustBashSession::new();
        xz_bash
            .inner
            .fs
            .lock()
            .unwrap()
            .write_file(
                "/payload.bin",
                vec![0x00, 0x01, 0x02, 0x03, 0x7f, 0x80, 0xff, 0xfe],
            )
            .unwrap();
        let xz_create = xz_bash.exec(
            "tar -cJf /payload.tar.xz /payload.bin",
            JustBashExecOptions::new(),
        );
        assert_eq!(xz_create.exit_code, 2);
        assert!(
            xz_create
                .stderr
                .contains("xz compression is disabled by default (native codec risk)")
        );
    }

    #[test]
    fn r10jb_tar_binary_null_all_bytes_pipe_and_special_filename_rows() {
        // tar.binary.test.ts: archive and extract a file with embedded null bytes.
        let null_bash = JustBashSession::new();
        null_bash
            .inner
            .fs
            .lock()
            .unwrap()
            .write_file("/src/nulls.bin", vec![0x41, 0x00, 0x42, 0x00, 0x43])
            .unwrap();
        null_bash.exec(
            "tar -cf /archive.tar -C /src nulls.bin; tar -xf /archive.tar -C /dest",
            JustBashExecOptions::new(),
        );
        assert_eq!(
            null_bash.read_file_buffer("/dest/nulls.bin").unwrap(),
            vec![0x41, 0x00, 0x42, 0x00, 0x43]
        );

        // archive and extract a file with all 256 byte values
        let all_bash = JustBashSession::new();
        let all_bytes: Vec<u8> = (0u16..256).map(|v| v as u8).collect();
        all_bash
            .inner
            .fs
            .lock()
            .unwrap()
            .write_file("/src/allbytes.bin", all_bytes.clone())
            .unwrap();
        all_bash.exec(
            "tar -cf /archive.tar -C /src allbytes.bin; tar -xf /archive.tar -C /dest",
            JustBashExecOptions::new(),
        );
        assert_eq!(
            all_bash.read_file_buffer("/dest/allbytes.bin").unwrap(),
            all_bytes
        );

        // list archive piped through cat (binary stdin)
        let pipe_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/src/file.txt", "content"),
        );
        pipe_bash.exec(
            "tar -cf /archive.tar -C /src file.txt",
            JustBashExecOptions::new(),
        );
        let piped_list = pipe_bash.exec("cat /archive.tar | tar -t", JustBashExecOptions::new());
        assert_eq!(piped_list.exit_code, 0);
        assert!(piped_list.stdout.contains("file.txt"));

        // extract archive piped through cat
        let extract_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/src/data.txt", "hello world"),
        );
        extract_bash.exec(
            "tar -cf /archive.tar -C /src data.txt",
            JustBashExecOptions::new(),
        );
        extract_bash.exec(
            "cat /archive.tar | tar -x -C /dest",
            JustBashExecOptions::new(),
        );
        assert_eq!(
            extract_bash
                .exec("cat /dest/data.txt", JustBashExecOptions::new())
                .stdout,
            "hello world"
        );

        // gzip archive piped through cat
        let gz_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/src/file.txt", "compressed content"),
        );
        gz_bash.exec(
            "tar -czf /archive.tar.gz -C /src file.txt",
            JustBashExecOptions::new(),
        );
        gz_bash.exec(
            "cat /archive.tar.gz | tar -xz -C /dest",
            JustBashExecOptions::new(),
        );
        assert_eq!(
            gz_bash
                .exec("cat /dest/file.txt", JustBashExecOptions::new())
                .stdout,
            "compressed content"
        );

        // bzip2 archive piped through cat
        let bz_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/src/file.txt", "bzip2 content"),
        );
        bz_bash.exec(
            "tar -cjf /archive.tar.bz2 -C /src file.txt",
            JustBashExecOptions::new(),
        );
        bz_bash.exec(
            "cat /archive.tar.bz2 | tar -xj -C /dest",
            JustBashExecOptions::new(),
        );
        assert_eq!(
            bz_bash
                .exec("cat /dest/file.txt", JustBashExecOptions::new())
                .stdout,
            "bzip2 content"
        );

        // reject xz compression by default (binary stdin section)
        let xz_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/src/file.txt", "xz content"),
        );
        let xz = xz_bash.exec(
            "tar -cJf /archive.tar.xz -C /src file.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(xz.exit_code, 2);
        assert!(xz.stderr.contains("disabled by default"));

        // reject zstd compression by default (binary stdin section)
        let zstd_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/src/file.txt", "zstd content"),
        );
        let zstd = zstd_bash.exec(
            "tar --zstd -cf /archive.tar.zst -C /src file.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(zstd.exit_code, 2);
        assert!(zstd.stderr.contains("disabled by default"));

        // UTF-8 archive and extract with gzip
        let utf8_gz_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/src/data.txt", "compressed data"),
        );
        utf8_gz_bash.exec(
            "tar -czf /archive.tar.gz -C /src data.txt; tar -xzf /archive.tar.gz -C /dest",
            JustBashExecOptions::new(),
        );
        assert_eq!(
            utf8_gz_bash
                .exec("cat /dest/data.txt", JustBashExecOptions::new())
                .stdout,
            "compressed data"
        );

        // filenames with special characters survive the listing
        let special_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/src/file-name_123.txt", "special filename"),
        );
        special_bash.exec(
            "tar -cf /archive.tar -C /src file-name_123.txt",
            JustBashExecOptions::new(),
        );
        assert!(
            special_bash
                .exec("tar -tf /archive.tar", JustBashExecOptions::new())
                .stdout
                .contains("file-name_123.txt")
        );
    }

    #[test]
    fn r11jb_tar_native_codec_decode_gates_and_utf8_stdin_pipe() {
        // tar.security.test.ts:93/100 createXz/createZstdCompressedArchive reject by
        // default: at the tar command surface, -cJf (xz) and --zstd encode fail closed
        // with the native-codec-risk message and exit 2.
        let create_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/src/test.txt", "data"),
        );
        let xz_create = create_bash.exec(
            "tar -cJf /out.tar.xz -C /src test.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(xz_create.exit_code, 2);
        assert!(
            xz_create
                .stderr
                .contains("xz compression is disabled by default (native codec risk)"),
            "xz create gate message: {:?}",
            xz_create.stderr
        );
        let zstd_create = create_bash.exec(
            "tar --zstd -cf /out.tar.zst -C /src test.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(zstd_create.exit_code, 2);
        assert!(
            zstd_create
                .stderr
                .contains("zstd compression is disabled by default (native codec risk)"),
            "zstd create gate message: {:?}",
            zstd_create.stderr
        );

        // tar.security.test.ts:107 parseXzCompressedArchive rejects by default: an
        // archive carrying the real xz stream magic (FD 37 7A 58 5A 00) is never handed
        // to a native decoder; extraction fails closed with the decompression message.
        let xz_bash = JustBashSession::new();
        let mut xz_payload = vec![0xFD, 0x37, 0x7A, 0x58, 0x5A, 0x00];
        xz_payload.extend_from_slice(&[0x01, 0x02, 0x03]);
        xz_bash
            .inner
            .fs
            .lock()
            .unwrap()
            .write_file("/archive.tar.xz", xz_payload)
            .unwrap();
        let xz_extract = xz_bash.exec(
            "mkdir /dest && tar -xf /archive.tar.xz -C /dest",
            JustBashExecOptions::new(),
        );
        assert_eq!(xz_extract.exit_code, 2);
        assert!(
            xz_extract
                .stderr
                .contains("xz decompression is disabled by default (native codec risk)"),
            "xz parse gate message: {:?}",
            xz_extract.stderr
        );

        // tar.security.test.ts:115 parseZstdCompressedArchive rejects by default: the
        // real zstd frame magic (28 B5 2F FD) is likewise fail-closed on extract.
        let zstd_bash = JustBashSession::new();
        let mut zstd_payload = vec![0x28, 0xB5, 0x2F, 0xFD];
        zstd_payload.extend_from_slice(&[0x01, 0x02, 0x03]);
        zstd_bash
            .inner
            .fs
            .lock()
            .unwrap()
            .write_file("/archive.tar.zst", zstd_payload)
            .unwrap();
        let zstd_extract = zstd_bash.exec(
            "mkdir /dest && tar -xf /archive.tar.zst -C /dest",
            JustBashExecOptions::new(),
        );
        assert_eq!(zstd_extract.exit_code, 2);
        assert!(
            zstd_extract
                .stderr
                .contains("zstd decompression is disabled by default (native codec risk)"),
            "zstd parse gate message: {:?}",
            zstd_extract.stderr
        );

        // tar.utf8-stdin.test.ts:5 round-trips multibyte file content through a
        // `tar -cf - dir | tar -xOf - dir/k.txt` pipe.
        let utf8_bash = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/dir/k.txt", "한글 / café / 漢字\n"),
        );
        let piped = utf8_bash.exec(
            "cd / && tar -cf - dir | tar -xOf - dir/k.txt",
            JustBashExecOptions::new(),
        );
        assert_eq!(piped.exit_code, 0, "pipe stderr: {:?}", piped.stderr);
        assert_eq!(piped.stdout, "한글 / café / 漢字\n");
    }

    #[test]
    fn jbc46_small_command_leftovers_od_tac_help_touch_pwd_true_sleep_rows() {
        let bash = JustBashSession::with_options(
            JustBashSessionOptions::new()
                .with_file("/a/.keep", "")
                .with_file("/b/.keep", "")
                .with_file("/c/.keep", "")
                .with_file("/parent/child/.keep", "")
                .with_file("/tmp/tac.txt", "line1\nline2\nline3\n")
                .with_file("/tmp/od.txt", "AB"),
        );

        assert_eq!(
            bash.exec("echo -e \"a\\nb\\nc\" | tac", JustBashExecOptions::new())
                .stdout,
            "c\nb\na\n"
        );
        assert_eq!(
            bash.exec("echo hello | tac", JustBashExecOptions::new())
                .stdout,
            "hello\n"
        );
        assert_eq!(
            bash.exec("echo -n '' | tac", JustBashExecOptions::new())
                .stdout,
            ""
        );
        assert_eq!(
            bash.exec("tac /tmp/tac.txt", JustBashExecOptions::new())
                .stdout,
            "line3\nline2\nline1\n"
        );
        let missing_tac = bash.exec("tac /missing.txt", JustBashExecOptions::new());
        assert_eq!(missing_tac.exit_code, 1);
        assert!(missing_tac.stderr.contains("No such file or directory"));
        assert_eq!(
            bash.exec("echo -n A | od -An", JustBashExecOptions::new())
                .stdout,
            " 101\n"
        );
        assert_eq!(
            bash.exec("echo -n hi | od -c", JustBashExecOptions::new())
                .stdout,
            "0000000    h   i\n0000002\n"
        );
        assert_eq!(
            bash.exec("od /tmp/od.txt", JustBashExecOptions::new())
                .stdout,
            "0000000  101 102\n0000002\n"
        );
        let missing_od = bash.exec("od /missing.txt", JustBashExecOptions::new());
        assert_eq!(missing_od.exit_code, 1);
        assert!(missing_od.stderr.contains("No such file or directory"));
        assert!(
            bash.exec("help", JustBashExecOptions::new())
                .stdout
                .contains("just-bash shell builtins")
        );
        assert!(
            bash.exec("help cd", JustBashExecOptions::new())
                .stdout
                .contains("Change")
        );
        assert!(
            bash.exec("help export", JustBashExecOptions::new())
                .stdout
                .contains("export")
        );
        assert_eq!(
            bash.exec("help nonexistent", JustBashExecOptions::new())
                .exit_code,
            1
        );
        assert!(
            bash.exec("help -s cd", JustBashExecOptions::new())
                .stdout
                .contains("cd [-L|-P]")
        );
        assert!(
            bash.exec("help -s help", JustBashExecOptions::new())
                .stdout
                .contains("help [-s]")
        );
        assert!(
            bash.exec("help -- help", JustBashExecOptions::new())
                .stdout
                .contains("Display")
        );
        assert_eq!(
            bash.exec("touch /new.txt; cat /new.txt", JustBashExecOptions::new())
                .stdout,
            ""
        );
        bash.exec("touch /one.txt /two.txt", JustBashExecOptions::new());
        assert!(bash.file_exists("/one.txt"));
        assert!(bash.file_exists("/two.txt"));
        assert_eq!(
            bash.exec(
                "echo original > /existing.txt; touch /existing.txt; cat /existing.txt",
                JustBashExecOptions::new()
            )
            .stdout,
            "original\n"
        );
        bash.exec("touch /dir/subdir/new.txt", JustBashExecOptions::new());
        assert!(bash.file_exists("/dir/subdir/new.txt"));
        assert_eq!(
            bash.exec("touch", JustBashExecOptions::new()).stderr,
            "touch: missing file operand\n"
        );
        bash.exec(
            "touch relative.txt",
            JustBashExecOptions::new().with_cwd("/home/user"),
        );
        assert!(bash.file_exists("/home/user/relative.txt"));
        bash.exec(
            "touch '/file with spaces.txt' /.hidden",
            JustBashExecOptions::new(),
        );
        assert!(bash.file_exists("/file with spaces.txt"));
        assert!(bash.file_exists("/.hidden"));
        assert_eq!(
            bash.exec("pwd", JustBashExecOptions::new()).stdout,
            "/home/user\n"
        );
        assert_eq!(
            JustBashSession::with_options(JustBashSessionOptions::new().with_cwd("/"))
                .exec("pwd", JustBashExecOptions::new())
                .stdout,
            "/\n"
        );
        assert_eq!(
            bash.exec("cd /a; cd /b; cd /c; pwd", JustBashExecOptions::new())
                .stdout,
            "/c\n"
        );
        assert_eq!(
            bash.exec("cd /parent/child; cd ..; pwd", JustBashExecOptions::new())
                .stdout,
            "/parent\n"
        );
        assert_eq!(
            bash.exec("pwd ignored args", JustBashExecOptions::new())
                .stdout,
            "/home/user\n"
        );
        assert_eq!(bash.exec("true", JustBashExecOptions::new()).exit_code, 0);
        assert_eq!(
            bash.exec("true --help -x && echo yes", JustBashExecOptions::new())
                .stdout,
            "yes\n"
        );
        assert_eq!(bash.exec("false", JustBashExecOptions::new()).exit_code, 1);
        assert_eq!(
            bash.exec("false --help -x || echo no", JustBashExecOptions::new())
                .stdout,
            "no\n"
        );
        assert_eq!(
            bash.exec("sleep 0.001; echo awake", JustBashExecOptions::new())
                .stdout,
            "awake\n"
        );
        assert_eq!(
            bash.exec("sleep 1s 0.001m; echo summed", JustBashExecOptions::new())
                .stdout,
            "summed\n"
        );
        assert_eq!(
            bash.exec("sleep abc", JustBashExecOptions::new()).stderr,
            "sleep: invalid time interval 'abc'\n"
        );
        assert_eq!(
            bash.exec("sleep", JustBashExecOptions::new()).stderr,
            "sleep: missing operand\n"
        );
        assert!(
            bash.exec("sleep --help", JustBashExecOptions::new())
                .stdout
                .contains("sleep")
        );
    }

    // Upstream parity: packages/just-bash/src/commands/sleep/sleep.test.ts duration-capture rows.
    // Upstream injects a `sleep: async (ms) => { sleptMs = ms }` mock and asserts the captured
    // millisecond total. The Rust runtime caps the real wait to a tiny deadline, so the exact
    // parsed/summed/capped duration is verified directly through `sleep_total_ms`, which is the
    // same function `command_sleep` uses to compute the duration it would pass to the sleeper.
    #[test]
    fn r18jb_sleep_command_duration_capture_rows_parse_sum_and_cap() {
        let ms = |arg: &str| sleep_total_ms(&[arg.to_string()]).expect("duration should parse");

        // "should sleep for specified seconds" — sleep 2 -> 2000ms
        assert_eq!(ms("2"), 2000);
        // "should handle decimal seconds" — sleep 0.5 -> 500ms
        assert_eq!(ms("0.5"), 500);
        // "should handle seconds suffix" — sleep 3s -> 3000ms
        assert_eq!(ms("3s"), 3000);
        // "should handle minutes suffix" — sleep 2m -> 120000ms
        assert_eq!(ms("2m"), 120_000);
        // "should handle hours suffix" — sleep 1h -> 3600000ms
        assert_eq!(ms("1h"), 3_600_000);
        // "should handle days suffix" — sleep 1d -> capped to MAX_SLEEP_MS (1 hour)
        assert_eq!(ms("1d"), 3_600_000);
        // "should handle decimal values with suffix" — sleep 0.5m -> 30000ms
        assert_eq!(ms("0.5m"), 30_000);

        // "should sum multiple durations" — sleep 1 2 3 -> 6000ms (1+2+3 = 6 seconds)
        assert_eq!(
            sleep_total_ms(&["1".to_string(), "2".to_string(), "3".to_string()])
                .expect("durations should parse"),
            6000
        );
    }

    #[test]
    fn jbc38_small_posix_table_and_xargs_commands_match_upstream_rows() {
        let bash = JustBashSession::with_options(
            JustBashSessionOptions::new()
                .with_file("/left.txt", "a\nb\nc\n")
                .with_file("/right.txt", "b\nc\nd\n")
                .with_file("/one.txt", "a\nb\nc\n")
                .with_file("/two.txt", "1\n2\n3\n")
                .with_file("/join-a.txt", "1 apple\n2 banana\n3 cherry\n")
                .with_file("/join-b.txt", "1 red\n2 yellow\n3 red\n")
                .with_file("/table.txt", "name age\nalice 30\nbob 25\n")
                .with_file("/split.txt", "line1\nline2\nline3\n"),
        );

        assert_eq!(
            bash.exec("printf 'a\\tb' | expand -t 4", JustBashExecOptions::new())
                .stdout,
            "a   b"
        );
        assert_eq!(
            bash.exec(
                "printf '    hello' | unexpand -t 4",
                JustBashExecOptions::new()
            )
            .stdout,
            "\thello"
        );
        assert_eq!(
            bash.exec("echo 'hello world' | fold -w 5", JustBashExecOptions::new())
                .stdout,
            "hello\n worl\nd\n"
        );
        assert_eq!(
            bash.exec(
                "printf 'a\\n\\nb\\n' | nl -ba -w 3",
                JustBashExecOptions::new()
            )
            .stdout,
            "  1\ta\n  2\t\n  3\tb\n"
        );
        assert_eq!(
            bash.exec("paste /one.txt /two.txt", JustBashExecOptions::new())
                .stdout,
            "a\t1\nb\t2\nc\t3\n"
        );
        assert_eq!(
            bash.exec("paste -sd, /one.txt", JustBashExecOptions::new())
                .stdout,
            "a,b,c\n"
        );
        assert_eq!(
            bash.exec("comm -12 /left.txt /right.txt", JustBashExecOptions::new())
                .stdout,
            "b\nc\n"
        );
        assert_eq!(
            bash.exec("column -t /table.txt", JustBashExecOptions::new())
                .stdout,
            "name   age\nalice  30\nbob    25\n"
        );
        assert_eq!(
            bash.exec(
                "join -o '1.2,2.2' /join-a.txt /join-b.txt",
                JustBashExecOptions::new()
            )
            .stdout,
            "apple red\nbanana yellow\ncherry red\n"
        );
        assert_eq!(
            bash.exec("split -l 1 /split.txt part_", JustBashExecOptions::new())
                .exit_code,
            0
        );
        assert_eq!(
            bash.exec("cat part_aa part_ab", JustBashExecOptions::new())
                .stdout,
            "line1\nline2\n"
        );
        assert_eq!(
            bash.exec(
                "printf 'a b c' | xargs -n 1 echo",
                JustBashExecOptions::new()
            )
            .stdout,
            "a\nb\nc\n"
        );
        assert_eq!(
            bash.exec(
                "printf 'x\\ny' | xargs -I {} echo file-{}",
                JustBashExecOptions::new()
            )
            .stdout,
            "file-x\nfile-y\n"
        );

        // split.utf8-stdin.test.ts:5 preserves multibyte content across split
        // chunks — `cat /in.txt | split -l 1 - /tmp/chunk_` reads UTF-8 from
        // stdin and writes each line to its own byte-identical chunk file.
        let split_utf8 = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/in.txt", "한글\ncafé\n漢字\n"),
        );
        assert_eq!(
            split_utf8
                .exec(
                    "cat /in.txt | split -l 1 - /tmp/chunk_",
                    JustBashExecOptions::new()
                )
                .exit_code,
            0
        );
        assert_eq!(split_utf8.read_file("/tmp/chunk_aa").unwrap(), "한글\n");
        assert_eq!(split_utf8.read_file("/tmp/chunk_ab").unwrap(), "café\n");
        assert_eq!(split_utf8.read_file("/tmp/chunk_ac").unwrap(), "漢字\n");

        // join.utf8-stdin.test.ts:5 joins on ASCII keys while preserving
        // multibyte field values — `cat /a.txt | join - /b.txt` reads the left
        // table from stdin and keeps the non-ASCII field bytes intact.
        let join_utf8 = JustBashSession::with_options(
            JustBashSessionOptions::new()
                .with_file("/a.txt", "1 한글\n2 café\n")
                .with_file("/b.txt", "1 韓国\n2 法国\n"),
        );
        let join_out = join_utf8.exec("cat /a.txt | join - /b.txt", JustBashExecOptions::new());
        assert_eq!(join_out.exit_code, 0);
        assert!(
            join_out.stdout.contains("한글"),
            "stdout: {:?}",
            join_out.stdout
        );
        assert!(
            join_out.stdout.contains("韓国"),
            "stdout: {:?}",
            join_out.stdout
        );
        assert!(
            join_out.stdout.contains("café"),
            "stdout: {:?}",
            join_out.stdout
        );
        assert!(
            join_out.stdout.contains("法国"),
            "stdout: {:?}",
            join_out.stdout
        );

        // xargs.command-name-quoting.test.ts:5 executes quoted command names
        // containing spaces — `xargs -I {} '/bin/my cmd.sh' {}` invokes the
        // quoted user-script path verbatim per input item, passing the
        // substituted argument as `$1` to the script body.
        let quoting = JustBashSession::with_options(
            JustBashSessionOptions::new().with_file("/bin/my cmd.sh", "echo XARGS:$1\n"),
        );
        assert_eq!(
            quoting
                .exec("chmod +x '/bin/my cmd.sh'", JustBashExecOptions::new())
                .exit_code,
            0
        );
        let quoting_run = quoting.exec(
            "printf '/dir/f.txt\\n' | xargs -I {} '/bin/my cmd.sh' {}",
            JustBashExecOptions::new(),
        );
        assert_eq!(quoting_run.stdout, "XARGS:/dir/f.txt\n");
        assert_eq!(quoting_run.stderr, "");
        assert_eq!(quoting_run.exit_code, 0);
    }

